import {itemHTML,offerHTML,matches,esc} from './render.mjs';
const data=JSON.parse(document.querySelector('#site-data').textContent), current=data.issues.find(d=>d.digest_id===data.current);let filter='all';
const search=document.querySelector('#search'), scope=document.querySelector('#scope');
function render(){const q=search.value.trim();const issues=q&&scope.value==='all'?data.issues:[current];const selected=issues.flatMap(d=>d.items).filter(i=>i.category==='news'&&matches(i,q,filter));const normal=!q&&filter==='all';document.querySelector('#featured').hidden=!normal;document.querySelector('#news-list').innerHTML=selected.filter(i=>!normal||i.event_id!==current.focus_event_id).map((i,n)=>itemHTML(i,n)).join('')||'<p class="empty">没有匹配新闻。</p>';document.querySelector('#search-status').textContent=q?`搜索 ${issues.length} 期，共 ${selected.length} 条新闻`:'';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});document.querySelector('#offer-list').innerHTML=data.offers.filter(o=>!q||JSON.stringify(o).toLowerCase().includes(q.toLowerCase())).map(offerHTML).join('')||'<p class="empty">没有匹配免费资源。</p>';document.querySelectorAll('[data-tool]').forEach(el=>el.hidden=!!q&&!el.textContent.toLowerCase().includes(q.toLowerCase()));}
search.addEventListener('input',render);scope.addEventListener('change',render);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render()}));document.querySelector('#clear').addEventListener('click',()=>{search.value='';filter='all';scope.value='all';render();search.focus()});render();
